WITH with_windows AS (SELECT *, AVG(shipping_fee) OVER (PARTITION BY store_id ORDER BY discount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS shipping_fee_avg_3, LAST_VALUE(discount) IGNORE NULLS OVER (ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_discount FROM orders WHERE store_id IS NULL) SELECT id, customer_id, store_id, order_date, status, channel, discount, shipping_fee, shipping_fee_avg_3, CASE WHEN status RLIKE '^(COMPLETED|RETURNED)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS status_zone FROM with_windows ORDER BY id DESC NULLS FIRST LIMIT 10;
